SELECT price_bucket, brand, total_stock_qty, avg_stock_qty FROM (SELECT CASE WHEN price >= 1180 THEN 'high' WHEN price >= 490 THEN 'mid' ELSE 'low' END AS price_bucket, brand, SUM(stock_qty) AS total_stock_qty, AVG(stock_qty) AS avg_stock_qty FROM products WHERE supplier_id IN (23, 26, 31) GROUP BY CASE WHEN price >= 1180 THEN 'high' WHEN price >= 490 THEN 'mid' ELSE 'low' END, brand) AS x WHERE total_stock_qty >= 1400;
